commit f3fa34dcad6fbfaadb5c68d67315149e6c652a93
Author: Nick Wellnhofer <wellnhofer@aevum.de>
Date:   Tue Dec 26 22:37:26 2023 +0100

    parser: Fix general entity parsing

    Clear namespace database.

    Ignore non-fatal errors.

diff --git a/parser.c b/parser.c
index cae2b7fd..47e56b3a 100644
--- a/parser.c
+++ b/parser.c
@@ -12320,262 +12320,284 @@ xmlSAXParseDTD(xmlSAXHandlerPtr sax, const xmlChar *ExternalID,
                tmp = ret->children;
                while (tmp != NULL) {
                    tmp->doc = NULL;
                    tmp = tmp->next;
                }
            }
        } else {
            ret = NULL;
        }
         xmlFreeDoc(ctxt->myDoc);
         ctxt->myDoc = NULL;
     }
     xmlFreeParserCtxt(ctxt);

     return(ret);
 }


 /**
  * xmlParseDTD:
  * @ExternalID:  a NAME* containing the External ID of the DTD
  * @SystemID:  a NAME* containing the URL to the DTD
  *
  * Load and parse an external subset.
  *
  * Returns the resulting xmlDtdPtr or NULL in case of error.
  */

 xmlDtdPtr
 xmlParseDTD(const xmlChar *ExternalID, const xmlChar *SystemID) {
     return(xmlSAXParseDTD(NULL, ExternalID, SystemID));
 }
 #endif /* LIBXML_VALID_ENABLED */

 /************************************************************************
  *                                                                     *
  *             Front ends when parsing an Entity                       *
  *                                                                     *
  ************************************************************************/

-static xmlNodePtr
+static xmlParserErrors
 xmlCtxtParseContent(xmlParserCtxtPtr ctxt, xmlParserInputPtr input,
-                    int hasTextDecl) {
+                    int hasTextDecl, xmlNodePtr *list) {
     xmlParserInputPtr oldInput;
     xmlNodePtr oldNode, root = NULL;
     int oldNameNr, oldSpaceNr, oldNodeNr;
     int oldWellFormed;
     int oldProgressive;
     int oldNodeLen, oldNodeMem;
+    xmlParserNsData *nsdb, *oldNsdb;
+    int ret;
+
+    if (list != NULL)
+        *list = NULL;

     if (((ctxt->depth > 40) && ((ctxt->options & XML_PARSE_HUGE) == 0)) ||
        (ctxt->depth > 100)) {
         xmlFatalErrMsg(ctxt, XML_ERR_ENTITY_LOOP,
                        "Maximum entity nesting depth exceeded");
-        return(NULL);
+        return(XML_ERR_ENTITY_LOOP);
+    }
+
+    root = xmlNewDocNode(ctxt->myDoc, NULL, BAD_CAST "pseudoroot", NULL);
+    if (root == NULL) {
+        xmlErrMemory(ctxt);
+        return(XML_ERR_NO_MEMORY);
+    }
+
+    /*
+     * We need to reset the namespace database, so that entities don't
+     * pick up namespaces from the parent of a reference.
+     */
+    nsdb = xmlParserNsCreate();
+    if (nsdb == NULL) {
+        xmlErrMemory(ctxt);
+        xmlFreeNode(root);
+        return(XML_ERR_NO_MEMORY);
     }

     oldNode = ctxt->node;
     oldInput = ctxt->input;
     oldWellFormed = ctxt->wellFormed;
     oldProgressive = ctxt->progressive;
     oldNodeLen = ctxt->nodelen;
     oldNodeMem = ctxt->nodemem;
+    oldNsdb = ctxt->nsdb;

     oldNameNr = ctxt->nameNr;
     oldSpaceNr = ctxt->spaceNr;
     oldNodeNr = ctxt->nodeNr;

-    root = xmlNewDocNode(ctxt->myDoc, NULL, BAD_CAST "pseudoroot", NULL);
-    if (root == NULL) {
-        xmlErrMemory(ctxt);
-        return(NULL);
-    }
-
     /*
      * TODO: It would be nice if we could simply push the input onto
      * the input stack. But there's still some code that assumes that
      * ctxt->inputNr > 1 means that we're inside a parameter entity.
      */
     ctxt->input = input;
     ctxt->progressive = 0;
     ctxt->nodelen = 0;
     ctxt->nodemem = 0;
+    ctxt->nsdb = nsdb;

     nameNsPush(ctxt, root->name, NULL, NULL, 0, 0);
     spacePush(ctxt, -1);
     nodePush(ctxt, root);

     if (hasTextDecl) {
         xmlDetectEncoding(ctxt);

         /*
          * Parse a possible text declaration first
          */
         if ((CMP5(CUR_PTR, '<', '?', 'x', 'm', 'l')) &&
             (IS_BLANK_CH(NXT(5)))) {
             xmlParseTextDecl(ctxt);
             /*
              * An XML-1.0 document can't reference an entity not XML-1.0
              */
             if ((xmlStrEqual(ctxt->version, BAD_CAST "1.0")) &&
                 (!xmlStrEqual(ctxt->input->version, BAD_CAST "1.0"))) {
                 xmlFatalErrMsg(ctxt, XML_ERR_VERSION_MISMATCH,
                                "Version mismatch between document and "
                                "entity\n");
             }
         }
     }

     ctxt->depth++;
     xmlParseContent(ctxt);
     ctxt->depth--;

     if ((RAW == '<') && (NXT(1) == '/')) {
        xmlFatalErr(ctxt, XML_ERR_NOT_WELL_BALANCED, NULL);
     } else if (RAW != 0) {
        xmlFatalErr(ctxt, XML_ERR_EXTRA_CONTENT, NULL);
     }

-    if ((ctxt->wellFormed == 0) &&
-        ((ctxt->recovery == 0) || (ctxt->errNo == XML_ERR_NO_MEMORY))) {
-        xmlFreeNode(root);
-        root = NULL;
+    if ((ctxt->wellFormed) ||
+        ((ctxt->recovery) && (ctxt->errNo != XML_ERR_NO_MEMORY))) {
+        if (list != NULL) {
+            xmlNodePtr cur;
+
+            /*
+             * Return the newly created nodeset after unlinking it from
+             * its pseudo parent.
+             */
+            cur = root->children;
+            *list = cur;
+            while (cur != NULL) {
+                cur->parent = NULL;
+                cur = cur->next;
+            }
+            root->children = NULL;
+            root->last = NULL;
+        }
+
+        ret = XML_ERR_OK;
+    } else {
+        ret = ctxt->errNo;
     }

     /*
      * If the entity wasn't balanced, we have to pop items from
      * several stacks.
      */
     while (ctxt->nameNr > oldNameNr) {
         xmlStartTag *tag = &ctxt->pushTab[ctxt->nameNr - 1];

         if (tag->nsNr != 0)
             xmlParserNsPop(ctxt, tag->nsNr);

         namePop(ctxt);
     }

     while (ctxt->spaceNr > oldSpaceNr) {
         spacePop(ctxt);
     }

     while (ctxt->nodeNr > oldNodeNr) {
         nodePop(ctxt);
     }

     ctxt->node = oldNode;
     ctxt->input = oldInput;
     ctxt->wellFormed = oldWellFormed && ctxt->wellFormed;
     ctxt->progressive = oldProgressive;
     ctxt->nodelen = oldNodeLen;
     ctxt->nodemem = oldNodeMem;
+    ctxt->nsdb = oldNsdb;

-    return(root);
+    xmlParserNsFree(nsdb);
